INSERT INTO `job_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`, `is_deleted`) VALUES (20, 730, 'GLUE_SHELL', '#!/bin/bash\n\n# 远程数据库配置\nREMOTE_DB_HOST=\"175.178.249.190\"\nREMOTE_DB_PORT=\"3306\"             \nREMOTE_DB_USER=\"root\"\nREMOTE_DB_PASSWORD=\"Yanhuo@Mysql0419\"\nREMOTE_DB_NAME=\"blog\"\n\n# 本地备份配置\nLOCAL_BACKUP_DIR=\"/Users/zhaowenpeng/Desktop/blog/mysql/\"\nMAX_BACKUPS=7  # 保留的备份份数（按数量而不是天数）\n\n# 创建本地备份目录\nmkdir -p $LOCAL_BACKUP_DIR || {\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 无法创建本地目录: $LOCAL_BACKUP_DIR\"\n    exit 1\n}\n\n# 生成带时间的备份文件名\nBACKUP_FILE=\"${REMOTE_DB_NAME}-$(date +%Y%m%d%H%M%S).sql.gz\"\n\n# 执行远程备份\necho \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 开始远程数据库备份...\"\nmysqldump -h $REMOTE_DB_HOST -P $REMOTE_DB_PORT -u$REMOTE_DB_USER -p$REMOTE_DB_PORT \\\n--single-transaction \\\n--routines \\\n--triggers \\\n$REMOTE_DB_NAME | gzip > $LOCAL_BACKUP_DIR/$BACKUP_FILE\n\n# 检查备份结果\nif [ $? -eq 0 ]; then\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份成功: $LOCAL_BACKUP_DIR/$BACKUP_FILE\"\nelse\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份失败!\"\n    rm -f $LOCAL_BACKUP_DIR/$BACKUP_FILE  # 删除不完整的备份文件\n    exit 1\nfi\n\n# 清理旧备份（保留最新MAX_BACKUPS份）\nBACKUP_FILES=($(ls -t $LOCAL_BACKUP_DIR/${REMOTE_DB_NAME}-*.sql.gz))\nCOUNT=${#BACKUP_FILES[@]}\n\nif [ $COUNT -gt $MAX_BACKUPS ]; then\n    DELETE_COUNT=$((COUNT - MAX_BACKUPS))\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 清理旧备份，删除${DELETE_COUNT}个\"\n    for ((i=MAX_BACKUPS; i<COUNT; i++)); do\n        rm -f \"${BACKUP_FILES[$i]}\"\n    done\nfi', 'blog备份', '2025-02-09 12:13:21', '2025-02-09 12:13:21', 0);
INSERT INTO `job_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`, `is_deleted`) VALUES (21, 730, 'GLUE_SHELL', '#!/bin/bash\n\n# 配置远程服务器信息\nREMOTE_USER=\"root\"  # 远程服务器的用户名\nREMOTE_HOST=\"175.178.249.190\"  # 远程服务器的IP地址或域名\nREMOTE_PORT=\"22\"           # 远程服务器的SSH端口（默认为22）\nREMOTE_MYSQL_USER=\"root\"  # 远程MySQL数据库的用户名\nREMOTE_MYSQL_PASSWORD=\"Yanhuo@Mysql0419\"  # 远程MySQL数据库的密码\nREMOTE_MYSQL_DB=\"blog\"  # 要备份的数据库名称\nREMOTE_MYSQL_PORT=\"3306\"         # 远程MySQL的端口（默认为3306）\n\n# 本地备份目录\nLOCAL_BACKUP_DIR=\"/Users/zhaowenpeng/Desktop/blog/mysql\"\n\n# 创建本地备份目录（如果不存在）\nmkdir -p \"$LOCAL_BACKUP_DIR\"\n\n# 当前日期，用于备份文件命名\nDATE=$(date +%Y%m%d_%H%M%S)\n\n# 备份文件名\nBACKUP_FILE=\"$LOCAL_BACKUP_DIR/$REMOTE_MYSQL_DB-$DATE.sql\"\n\n# 使用SSH在远程服务器上执行MySQL导出命令\nssh -p \"$REMOTE_PORT\" \"$REMOTE_USER@$REMOTE_HOST\" \"mysqldump -u $REMOTE_MYSQL_USER -p$REMOTE_MYSQL_PASSWORD -P $REMOTE_MYSQL_PORT $REMOTE_MYSQL_DB\" > \"$BACKUP_FILE\"\n\n# 检查备份是否成功\nif [ $? -eq 0 ]; then\n    echo \"备份成功，文件已保存到：$BACKUP_FILE\"\nelse\n    echo \"备份失败，请检查远程服务器和MySQL配置。\"\nfi', 'blog3', '2025-02-09 12:22:18', '2025-02-09 12:22:18', 0);
INSERT INTO `job_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`, `is_deleted`) VALUES (22, 730, 'GLUE_SHELL', '#!/bin/bash\n\n# 远程数据库配置\nREMOTE_DB_HOST=\"175.178.249.190\"\nREMOTE_DB_PORT=\"3306\"             \nREMOTE_DB_USER=\"root\"\nREMOTE_DB_PASSWORD=\"Yanhuo@Mysql0419\"\nREMOTE_DB_NAME=\"blog\"\n\n# 本地备份配置\nLOCAL_BACKUP_DIR=\"/Users/zhaowenpeng/Desktop/blog/mysql/\"\nMAX_BACKUPS=7  # 保留的备份份数（按数量而不是天数）\n\n# 创建本地备份目录\nmkdir -p $LOCAL_BACKUP_DIR || {\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 无法创建本地目录: $LOCAL_BACKUP_DIR\"\n    exit 1\n}\n\n# 生成带时间的备份文件名\nBACKUP_FILE=\"${REMOTE_DB_NAME}-$(date +%Y%m%d%H%M%S).sql.gz\"\n\n# 执行远程备份\necho \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 开始远程数据库备份...\"\nmysqldump -h $REMOTE_DB_HOST -P $REMOTE_DB_PORT -u$REMOTE_DB_USER -p$REMOTE_DB_PORT \\\n--single-transaction \\\n--routines \\\n--triggers \\\n$REMOTE_DB_NAME | gzip > $LOCAL_BACKUP_DIR/$BACKUP_FILE\n\n# 检查备份结果\nif [ $? -eq 0 ]; then\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份成功: $LOCAL_BACKUP_DIR/$BACKUP_FILE\"\nelse\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份失败!\"\n    rm -f $LOCAL_BACKUP_DIR/$BACKUP_FILE  # 删除不完整的备份文件\n    exit 1\nfi\n\n# 清理旧备份（保留最新MAX_BACKUPS份）\nBACKUP_FILES=($(ls -t $LOCAL_BACKUP_DIR/${REMOTE_DB_NAME}-*.sql.gz))\nCOUNT=${#BACKUP_FILES[@]}\n\nif [ $COUNT -gt $MAX_BACKUPS ]; then\n    DELETE_COUNT=$((COUNT - MAX_BACKUPS))\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 清理旧备份，删除${DELETE_COUNT}个\"\n    for ((i=MAX_BACKUPS; i<COUNT; i++)); do\n        rm -f \"${BACKUP_FILES[$i]}\"\n    done\nfi', 'blog4', '2025-02-09 12:25:08', '2025-02-09 12:25:08', 0);
