INSERT INTO `job_logglue` (`id`, `job_id`, `glue_type`, `glue_source`, `glue_remark`, `create_time`, `update_time`, `is_deleted`) VALUES (29, 760, 'GLUE_SHELL', '#!/bin/bash\n\n# 远程数据库配置\nREMOTE_DB_HOST=\"175.178.249.190\"\nREMOTE_DB_PORT=\"3306\"             \nREMOTE_DB_USER=\"root\"\nREMOTE_DB_PASSWORD=\"Yanhuo@Mysql0419\"\nREMOTE_DB_NAME=\"yanhuo\"\n\n# 本地备份配置\nLOCAL_BACKUP_DIR=\"/Users/zhaowenpeng/Desktop/blog/yanhuo/\"\nMAX_BACKUPS=7  # 保留的备份份数（按数量而不是天数）\n\n# 创建本地备份目录\nmkdir -p $LOCAL_BACKUP_DIR || {\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 无法创建本地目录: $LOCAL_BACKUP_DIR\"\n    exit 1\n}\n\n# 生成带时间的备份文件名\nBACKUP_FILE=\"${REMOTE_DB_NAME}-$(date +%Y%m%d%H%M%S).sql.gz\"\n\n# 执行远程备份\necho \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 开始远程数据库备份...\"\nmysqldump -h $REMOTE_DB_HOST -P $REMOTE_DB_PORT -u$REMOTE_DB_USER -p$REMOTE_DB_PASSWORD \\\n--single-transaction \\\n--routines \\\n--triggers \\\n$REMOTE_DB_NAME | gzip > $LOCAL_BACKUP_DIR/$BACKUP_FILE\n\n# 检查备份结果\nif [ $? -eq 0 ]; then\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份成功: $LOCAL_BACKUP_DIR/$BACKUP_FILE\"\nelse\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 备份失败!\"\n    rm -f $LOCAL_BACKUP_DIR/$BACKUP_FILE  # 删除不完整的备份文件\n    exit 1\nfi\n\n# 清理旧备份（保留最新MAX_BACKUPS份）\nBACKUP_FILES=($(ls -t $LOCAL_BACKUP_DIR/${REMOTE_DB_NAME}-*.sql.gz))\nCOUNT=${#BACKUP_FILES[@]}\n\nif [ $COUNT -gt $MAX_BACKUPS ]; then\n    DELETE_COUNT=$((COUNT - MAX_BACKUPS))\n    echo \"[$(date +\'%Y-%m-%d %H:%M:%S\')] 清理旧备份，删除${DELETE_COUNT}个\"\n    for ((i=MAX_BACKUPS; i<COUNT; i++)); do\n        rm -f \"${BACKUP_FILES[$i]}\"\n    done\nfi', 'yanhuo1', '2025-02-16 20:14:07', '2025-02-16 20:14:07', 0);
